/**
 * The shell-model atom (atom/ShellAtom.tsx). WHAT IS PINNED: the shell rule's
 * electron counts against RDKit's periodic table (GetNOuterElecs, generated by
 * scripts/gen_shell_atom.py into shellModel.generated.ts) for every supported
 * element; the formal charge count (valence minus owned) against RDKit's formal
 * charge on the three scene presets and a wider set of centre atoms; the
 * drawing places exactly the electrons it claims; and chapter 2's scene mounts
 * the explorer.
 *
 * The lone pair counts in the generated tables are themselves derived from
 * RDKit's formal charge and bond orders, so the formal charge check pins the
 * shell rule's valence count and the owned-electron arithmetic, not an
 * independent lone pair count.
 */
import { describe, expect, it } from "vitest";

import { formalCharge, formalChargeLine, ownedElectrons, placeElectrons, shellCounts, SHELL_SYMBOLS, SUPPORTED_Z, valenceElectrons } from "../atom/shellModel";
import { ATOM_PRESETS, FORMAL_CASES, RDKIT_OUTER_ELECTRONS } from "../atom/shellModel.generated";
import { STORY_CHAPTERS } from "../content/u0";

describe("the shell rule", () => {
  it("covers exactly the elements the generator read from RDKit", () => {
    expect(SUPPORTED_Z.map(String).sort()).toEqual(Object.keys(RDKIT_OUTER_ELECTRONS).sort());
  });

  it("gives every supported element RDKit's valence electron count and symbol", () => {
    for (const z of SUPPORTED_Z) {
      const rd = RDKIT_OUTER_ELECTRONS[String(z)]!;
      expect(SHELL_SYMBOLS[z], `Z=${z}`).toBe(rd.symbol);
      expect(valenceElectrons(z), rd.symbol).toBe(rd.outer);
    }
  });

  it("sums to Z and never overfills a shell (2n^2)", () => {
    for (const z of SUPPORTED_Z) {
      const shells = shellCounts(z);
      expect(shells.reduce((a, b) => a + b, 0), String(z)).toBe(z);
      shells.forEach((count, i) => expect(count, `${z} shell ${i + 1}`).toBeLessThanOrEqual(2 * (i + 1) ** 2));
    }
  });

  it("draws the shells the course talks about", () => {
    expect(shellCounts(6)).toEqual([2, 4]);
    expect(shellCounts(17)).toEqual([2, 8, 7]);
    expect(shellCounts(19)).toEqual([2, 8, 8, 1]);
    expect(shellCounts(35)).toEqual([2, 8, 18, 7]);
    expect(shellCounts(53)).toEqual([2, 8, 18, 18, 7]);
  });

  it("refuses an element it does not claim", () => {
    expect(() => shellCounts(26)).toThrow();
  });
});

describe("the formal charge count", () => {
  it("matches RDKit's formal charge on the three scene presets", () => {
    expect(ATOM_PRESETS.map((p) => p.id)).toEqual(["c-methane", "n-ammonium", "o-hydroxide"]);
    for (const p of ATOM_PRESETS) expect(formalCharge(p.z, p), p.id).toBe(p.formalCharge);
    const n = ATOM_PRESETS.find((p) => p.id === "n-ammonium")!;
    expect(ownedElectrons(n)).toBe(4);
    expect(formalChargeLine(n.z, n)).toBe("N brought 5 and owns 4: formal charge 5 − 4 = +1.");
  });

  it("matches RDKit's formal charge on every wider case", () => {
    expect(FORMAL_CASES.length).toBeGreaterThanOrEqual(10);
    for (const c of FORMAL_CASES) expect(formalCharge(c.z, c), c.name).toBe(c.formalCharge);
  });
});

describe("the drawing", () => {
  it("places every electron of the free atom on its shell", () => {
    for (const z of SUPPORTED_Z) {
      const { electrons } = placeElectrons(z);
      expect(electrons.length, String(z)).toBe(z);
      const shells = shellCounts(z);
      shells.forEach((count, i) => expect(electrons.filter((e) => e.shell === i + 1).length).toBe(count));
    }
  });

  it("puts the owned electrons on the valence shell in a molecule, with one stub per bond", () => {
    for (const p of [...ATOM_PRESETS, ...FORMAL_CASES]) {
      const { electrons, bonds } = placeElectrons(p.z, p);
      const shells = shellCounts(p.z);
      const outer = electrons.filter((e) => e.shell === shells.length);
      expect(outer.length, p.symbol).toBe(ownedElectrons(p));
      expect(outer.filter((e) => e.role === "lone").length).toBe(2 * p.lonePairs);
      expect(bonds.length).toBe(p.bonds.length);
    }
  });
});

describe("chapter 2 mounts the explorer", () => {
  it("has one explore step on the bonds and formal charge scene", () => {
    const ch2 = STORY_CHAPTERS.find((c) => c.title === "Bonds and formal charge")!;
    expect(ch2.scene.steps.filter((s) => s.explore === "shellAtom")).toHaveLength(1);
  });
});
